def _result_id(case_id: str) -> str | None:
    """Return the server ID that the helper returns: delete returns nothing, create the created server."""
    if case_id.endswith(".delete_and_poll"):
        return None
    if case_id.endswith(".create_and_poll"):
        return CREATED_ID
    return "test"


